-- Function: public.fn_validate_and_set_organization
-- Backup generated on 2026-10-25 20:33:47

CREATE OR REPLACE FUNCTION public.fn_validate_and_set_organization(p_user_id uuid, p_organization_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(is_valid boolean, tenant_id uuid)  LANGUAGE plpgsql AS $function$ DECLARE     v_tenant_id UUID; BEGIN     IF p_organization_id IS NOT NULL THEN         SELECT o.tenant_id INTO v_tenant_id         FROM organization_memberships om         JOIN organizations o ON om.organization_id = o.id         WHERE om.user_id = p_user_id           AND om.organization_id = p_organization_id           AND om.status = 'Active'         LIMIT 1;          IF v_tenant_id IS NOT NULL THEN             RETURN QUERY SELECT TRUE, v_tenant_id;         ELSE             RETURN QUERY SELECT FALSE, NULL::UUID;         END IF;     ELSE         IF EXISTS (SELECT 1 FROM family_relationships WHERE user_id = p_user_id) THEN             SELECT u.tenant_id INTO v_tenant_id FROM users u WHERE u.id = p_user_id;             RETURN QUERY SELECT TRUE, v_tenant_id;         ELSE             RETURN QUERY SELECT FALSE, NULL::UUID;         END IF;     END IF; END; $function$ ;
